code_example:
#include <iostream>
#include <memory>
class A { public: int a; A(int a_val) : a(a_val) {} };
class B : virtual public A { public: int b; B(int a_val, int b_val) : A(a_val), b(b_val) {} };
class C : virtual public A { public: int c; C(int a_val, int c_val) : A(a_val), c(c_val) {} };
class D : public B, public C { public: int d; D(int a_val, int b_val, int c_val, int d_val) : A(a_val), B(a_val, b_val), C(a_val, c_val), d(d_val) {} };
int main() {
  D objD(10, 20, 30, 40);
  std::cout << &objD.a << " " << &objD.b << " " << &objD.c << " " << &objD.d << std::endl; //Observe memory layout; note single A.
  return 0;
}
